def test_changeset_tokens_and_mcp(planned: Path, tmp_path: Path) -> None:
    import ast

    from pitchdeck.change_set import (
        DeckStructureOp,
        EditProposal,
        SetSlideField,
        apply_proposal,
        mint_confirmation_token,
        simulate_proposal,
    )
    from pitchdeck.mcp_server import handle_request
    from pitchdeck.revisions import current_revision

    deck = load_yaml(planned / "deck.public.yaml", DeckManifest)
    sid = sorted(deck.slides, key=lambda s: s.order)[1].id
    rev = current_revision(planned)

    # Cosmetic proposal: simulate then apply without a token.
    cosmetic = EditProposal(
        base_revision=rev,
        ops=[SetSlideField(slide_id=sid, field="footer", value="proposal footer")],
        rationale="cosmetic footer", idempotency_key="idem-cosmetic-1",
    )
    assert simulate_proposal(planned, cosmetic)["would_pass"]
    assert apply_proposal(planned, tmp_path / "ui", cosmetic)["applied"]

    # Governance proposal (delete) requires a token.
    rev2 = current_revision(planned)
    governance = EditProposal(
        base_revision=rev2,
        ops=[DeckStructureOp(deck_op="delete", slide_id=sid)],
        rationale="drop slide", idempotency_key="idem-gov-1",
    )
    with pytest.raises(PermissionError, match="confirmation token"):
        apply_proposal(planned, tmp_path / "ui", governance)

    # Cross-proposal token rejected; correct token works once; replay rejected.
    other = governance.model_copy(update={"idempotency_key": "idem-gov-2"})
    wrong = mint_confirmation_token(planned, other)
    with pytest.raises(PermissionError, match="different proposal"):
        apply_proposal(planned, tmp_path / "ui", governance, token=wrong)
    token = mint_confirmation_token(planned, governance)
    assert apply_proposal(planned, tmp_path / "ui", governance, token=token)["governance"]
    restore = EditProposal(
        base_revision=current_revision(planned),
        ops=[DeckStructureOp(deck_op="delete", slide_id=deck.slides[0].id)],
        rationale="x", idempotency_key="idem-gov-3",
    )
    with pytest.raises(PermissionError, match="unknown or already used"):
        apply_proposal(planned, tmp_path / "ui", restore, token=token)

    # Stale revision refuses.
    stale = EditProposal(
        base_revision=rev,  # long since advanced
        ops=[SetSlideField(slide_id="03-thesis", field="footer", value="x")],
        rationale="stale", idempotency_key="idem-stale-1",
    )
    result = simulate_proposal(planned, stale)  # simulate ignores CAS (dry)
    if result["would_pass"]:
        with pytest.raises(ValueError, match="revision"):
            apply_proposal(planned, tmp_path / "ui", stale)

    # MCP adapter: history works, token minting is NOT exposed, imports are clean.
    history = handle_request({"tool": "pitchdeck_history", "arguments": {"bundle_dir": str(planned)}})
    assert "revision" in history
    unknown = handle_request({"tool": "pitchdeck_mint_token", "arguments": {"bundle_dir": str(planned)}})
    assert "unknown tool" in unknown["error"]
    tree = ast.parse((Path(__file__).resolve().parents[1] / "src" / "pitchdeck" / "mcp_server.py").read_text())
    imported = {
        node.module for node in ast.walk(tree) if isinstance(node, ast.ImportFrom) and node.module
    }
    assert "pitchdeck.change_set" not in imported  # relative imports only
    for mod in imported:
        assert mod in {"__future__", "change_set", "revisions", "pathlib"} or not mod.startswith("pitchdeck"), mod
    mint_exposed = any(
        isinstance(n, ast.Name) and n.id == "mint_confirmation_token" for n in ast.walk(tree)
    )
    assert not mint_exposed, "MCP module must not mint confirmation tokens"


def test_claim_decide_and_replay(planned: Path, tmp_path: Path) -> None:
    import json as _json

    from pitchdeck.claim_decide import DECISION_LOG, decide_claim, replay_decisions

    ledger = load_yaml(planned / "claim_ledger.yaml", ClaimLedger)
    candidates = [c for c in ledger.claims if c.status.value == "candidate"]
    plain = next(c for c in candidates if c.risk.value != "high" and not any(ch.isdigit() for ch in c.text))
    risky = next(c for c in candidates if c.risk.value == "high" or any(ch.isdigit() for ch in c.text))

    # Individual decision writes provenance + audit line.
    result = decide_claim(planned, tmp_path / "ui", claim_id=plain.id, decision="approve", decided_by="human-tester")
    after = load_yaml(planned / "claim_ledger.yaml", ClaimLedger)
    decided = next(c for c in after.claims if c.id == plain.id)
    assert decided.status.value == "approved" and decided.approval.approved_by == "human-tester"
    assert not decided.approval.fixture
    log_lines = (planned / DECISION_LOG).read_text().splitlines()
    assert _json.loads(log_lines[-1])["claim_id"] == plain.id

    # Batch context refuses high-risk/numeric claims.
    with pytest.raises(PermissionError, match="batch"):
        decide_claim(planned, tmp_path / "ui", claim_id=risky.id, decision="approve", decided_by="h", batch=True)

    # Decisions replay deterministically onto a fresh copy of the bundle.
    import shutil

    copy = tmp_path / "replay-bundle"
    shutil.copytree(planned, copy, ignore=shutil.ignore_patterns(".history", DECISION_LOG))
    replayed = replay_decisions(copy, tmp_path / "ui2", planned / DECISION_LOG)
    assert replayed["replayed"] == len(log_lines)
    replay_ledger = load_yaml(copy / "claim_ledger.yaml", ClaimLedger)
    assert next(c for c in replay_ledger.claims if c.id == plain.id).status.value == "approved"


def test_deck_document_canonical_schema(tmp_path):
    """#1263: the whole deck compiles into ONE strict document — every slide as
    in-bounds bbox elements, referential integrity enforced, deterministic."""
    import json

    from pitchdeck.document import DeckDocument, compile_document, export_json_schema

    bundle = Path(__file__).parent.parent / "examples" / "sparta-explorer"
    doc = compile_document(bundle)
    assert doc.schema_ == "pitchdeck.deck_document.v1"
    assert len(doc.slides) >= 1 and all(s.elements for s in doc.slides)
    for slide in doc.slides:
        for el in slide.elements:
            assert el.bbox.x + el.bbox.w <= 1.0001 and el.bbox.y + el.bbox.h <= 1.0001
    # deterministic round-trip, and the dump revalidates strictly
    dump = doc.model_dump_json(by_alias=True)
    assert dump == compile_document(bundle).model_dump_json(by_alias=True)
    DeckDocument.model_validate(json.loads(dump))
    # committed JSON Schema artifact matches the models (generated, not hand-edited)
    committed = json.loads((Path(__file__).parent.parent / "schemas" / "pitchdeck.deck_document.v1.schema.json").read_text())
    assert committed == export_json_schema()
    # referential integrity fails closed
    broken = json.loads(dump)
    broken["slides"][0]["claim_ids"] = ["no-such-claim"]
    import pytest as _pytest

    with _pytest.raises(Exception):
        DeckDocument.model_validate(broken)


